import json
from pathlib import Path

ROOT=Path(__file__).parent
REL='.archify/workflow-moneymate-20261103-161801'
catalog=[]

def node(id,lane,col,label,sub='',type='backend',icon=None):
    v=dict(id=id,lane=lane,col=col,type=type,label=label)
    if sub:v['sublabel']=sub
    if icon:v['icon']=icon
    return v
def edge(a,b,label='',role=None):
    v=dict(id=a+'-'+b,**{'from':a,'to':b})
    if label:v['label']=label
    if role:v['role']=role
    if role=='main':v['variant']='emphasis'
    if role=='error':v['variant']='security'
    return v
def save(slug,title,desc,lanes,nodes,edges,main,cards):
    d=dict(schema_version=2,diagram_type='workflow',meta=dict(title=title,output=f'{REL}/{slug}.html',quality_profile='showcase',legend={'entries':{'frontend':{'label':'Người dùng / giao diện'},'backend':{'label':'Xử lý nghiệp vụ'},'database':{'label':'Dữ liệu tại máy'},'security':{'label':'Kiểm tra / điều kiện'},'cloud':{'label':'Dịch vụ bên ngoài'},'messagebus':{'label':'Tác vụ nền'},'external':{'label':'Tệp / tác nhân'}}}),lanes=[dict(id=i,label=l,**({'variant':'exception'} if i=='err' else {})) for i,l in lanes],nodes=nodes,edges=edges,mainPath=main,cards=[dict(dot=color,title=t,items=items) for color,t,items in cards])
    (ROOT/(slug+'.json')).write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf-8')
    catalog.append((slug,title,desc))

